const body = $json;

if (!body.eventId || typeof body.eventId !== 'string') {
  throw new Error('Validation Error: Missing or invalid eventId.');
}

if (!body.eventType || typeof body.eventType !== 'string') {
  throw new Error('Validation Error: Missing or invalid eventType.');
}

const validTypes = [
  'booking.confirmed',
  'ticket.exchange.completed',
  'ticket.refund.completed',
  'ticket.checked_in'
];

if (!validTypes.includes(body.eventType)) {
  throw new Error(`Validation Error: Unsupported eventType ${body.eventType}`);
}

if (body.eventType !== 'ticket.checked_in' && !body.recipientEmail) {
  throw new Error('Validation Error: Missing recipientEmail for customer email notification.');
}

return [{
  json: {
    ...body,
    receivedAt: new Date().toISOString(),
    isValid: true
  }
}];

const ev = $json;
const customer = ev.customer || {};
const movie = ev.movie || {};
const show = ev.showtime || {};
const booking = ev.booking || {};
const seats = ev.seats || [];
const combos = ev.combos || [];

const formattedTotal = Number(booking.total || 0).toLocaleString('vi-VN') + ' VND';
const formattedTime = show.startsAt ? new Date(show.startsAt).toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' }) : 'Chưa xác định';

const combosHtml = combos.length > 0
  ? `<ul>${combos.map(c => `<li>${c.name} x ${c.quantity} (${Number(c.unitPrice).toLocaleString('vi-VN')} VND)</li>`).join('')}</ul>`
  : '<p>Không có combo bắp nước.</p>';

const html = `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: auto; padding: 20px; background-color: #0b0f19; color: #f3f4f6; border-radius: 12px; border: 1px solid #374151;">
  <div style="text-align: center; border-bottom: 2px solid #fbbf24; padding-bottom: 12px; margin-bottom: 20px;">
    <h1 style="color: #fbbf24; margin: 0; font-size: 24px;">✨ STARLIGHT CINEMA ✨</h1>
    <p style="color: #9ca3af; margin: 4px 0 0 0;">Xác nhận đặt vé thành công</p>
  </div>

  <p>Kính chào <strong>${customer.name || customer.email || 'Quý khách'}</strong>,</p>
  <p>Cảm ơn bạn đã lựa chọn Starlight Cinema. Dưới đây là thông tin chi tiết về vé xem phim của bạn:</p>

  <div style="background-color: #111827; border: 1px solid #1f2937; border-radius: 8px; padding: 16px; margin: 20px 0;">
    <p style="margin: 6px 0;">🎬 <strong>Phim:</strong> <span style="color: #60a5fa;">${movie.title || 'N/A'}</span></p>
    <p style="margin: 6px 0;">🏛️ <strong>Rạp:</strong> ${show.cinema || 'Starlight Cinema'}</p>
    <p style="margin: 6px 0;">🚪 <strong>Phòng chiếu:</strong> ${show.room || 'Phòng chiếu chính'}</p>
    <p style="margin: 6px 0;">⏰ <strong>Suất chiếu:</strong> <span style="color: #34d399;">${formattedTime}</span></p>
    <p style="margin: 6px 0;">💺 <strong>Số ghế:</strong> <strong style="color: #f59e0b;">${seats.join(', ') || 'N/A'}</strong></p>
    <p style="margin: 6px 0;">🧾 <strong>Mã đơn hàng:</strong> <code>${booking.id || 'N/A'}</code></p>
    <p style="margin: 6px 0;">💰 <strong>Tổng thanh toán:</strong> <strong style="color: #fbbf24; font-size: 16px;">${formattedTotal}</strong></p>
  </div>

  <div style="margin: 16px 0;">
    <h4 style="color: #e5e7eb; margin-bottom: 8px;">🍿 Bắp nước & Combo:</h4>
    ${combosHtml}
  </div>

  <div style="background-color: #1e1b4b; border-left: 4px solid #818cf8; padding: 12px; border-radius: 4px; margin: 20px 0;">
    <p style="margin: 0; font-size: 13px; color: #c7d2fe;">
      🎟️ <strong>Hướng dẫn check-in:</strong> Vui lòng đăng nhập vào tài khoản trên website Starlight Cinema, mở mục <strong>Vé của tôi</strong> để xuất trình mã QR điện tử tại quầy soát vé trước giờ chiếu ít nhất 15 phút.
    </p>
  </div>

  <p style="color: #9ca3af; font-size: 12px; text-align: center; margin-top: 30px; border-top: 1px solid #1f2937; padding-top: 12px;">
    Hệ thống thông báo tự động từ Starlight Cinema • Email này được tạo tự động, vui lòng không trả lời trực tiếp.
  </p>
</div>
`;

return [{
  json: {
    recipientEmail: ev.recipientEmail,
    subject: `[Starlight Cinema] Xác nhận đặt vé thành công: ${movie.title || 'Vé xem phim'}`,
    htmlText: html,
    eventId: ev.eventId
  }
}];

const ev = $json;
const exchange = ev.exchange || {};
const oldTickets = exchange.oldTickets || [];
const newTickets = exchange.newTickets || [];
const payableText = exchange.payable ? `${Number(exchange.payable).toLocaleString('vi-VN')} VND` : '0 VND';

const html = `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: auto; padding: 20px; background-color: #0b0f19; color: #f3f4f6; border-radius: 12px; border: 1px solid #374151;">
  <div style="text-align: center; border-bottom: 2px solid #3b82f6; padding-bottom: 12px; margin-bottom: 20px;">
    <h1 style="color: #3b82f6; margin: 0; font-size: 24px;">🔄 STARLIGHT CINEMA</h1>
    <p style="color: #9ca3af; margin: 4px 0 0 0;">Xác nhận đổi vé thành công</p>
  </div>

  <p>Kính chào Quý khách,</p>
  <p>Yêu cầu đổi vé xem phim của bạn đã được nhân viên hoàn tất theo đúng quy định:</p>

  <div style="background-color: #111827; border: 1px solid #1f2937; border-radius: 8px; padding: 16px; margin: 20px 0;">
    <p style="margin: 6px 0;">📋 <strong>Mã yêu cầu đổi:</strong> <code>${exchange.requestId || 'N/A'}</code></p>
    <p style="margin: 6px 0;">🎟️ <strong>Số lượng vé đã đổi:</strong> ${newTickets.length} vé</p>
    <p style="margin: 6px 0;">💺 <strong>Ghế mới:</strong> <strong style="color: #34d399;">${newTickets.map(t => t.seatLabel || t.id).join(', ')}</strong></p>
    <p style="margin: 6px 0;">💳 <strong>Chênh lệch thanh toán thêm:</strong> ${payableText}</p>
  </div>

  <p style="font-size: 13px; color: #9ca3af;">Vé cũ đã được thu hồi và cập nhật trạng thái đã đổi (REPLACED). Vé mới đã sẵn sàng trong tài khoản của bạn.</p>
</div>
`;

return [{
  json: {
    recipientEmail: ev.recipientEmail,
    subject: `[Starlight Cinema] Xác nhận hoàn tất đổi vé #${exchange.requestId || ''}`,
    htmlText: html,
    eventId: ev.eventId
  }
}];

const ev = $json;
const refund = ev.refund || {};
const amountText = refund.amount ? `${Number(refund.amount).toLocaleString('vi-VN')} VND` : '0 VND';

const html = `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: auto; padding: 20px; background-color: #0b0f19; color: #f3f4f6; border-radius: 12px; border: 1px solid #374151;">
  <div style="text-align: center; border-bottom: 2px solid #ef4444; padding-bottom: 12px; margin-bottom: 20px;">
    <h1 style="color: #ef4444; margin: 0; font-size: 24px;">💸 STARLIGHT CINEMA</h1>
    <p style="color: #9ca3af; margin: 4px 0 0 0;">Thông báo hoàn tiền vé thành công</p>
  </div>

  <p>Kính chào Quý khách,</p>
  <p>Giao dịch hoàn tiền cho vé xem phim của bạn đã được hệ thống Starlight Cinema xác nhận:</p>

  <div style="background-color: #111827; border: 1px solid #1f2937; border-radius: 8px; padding: 16px; margin: 20px 0;">
    <p style="margin: 6px 0;">📋 <strong>Mã yêu cầu hoàn:</strong> <code>${refund.requestId || 'N/A'}</code></p>
    <p style="margin: 6px 0;">💵 <strong>Số tiền hoàn lại:</strong> <strong style="color: #fbbf24;">${amountText}</strong></p>
    ${refund.reason ? `<p style="margin: 6px 0;">📝 <strong>Lý do:</strong> ${refund.reason}</p>` : ''}
  </div>

  <p style="font-size: 13px; color: #9ca3af;">Khoản hoàn sẽ được chuyển về tài khoản ban đầu theo thời gian quy định của ngân hàng hoặc cổng thanh toán.</p>
</div>
`;

return [{
  json: {
    recipientEmail: ev.recipientEmail,
    subject: `[Starlight Cinema] Xác nhận hoàn tiền vé #${refund.requestId || ''}`,
    htmlText: html,
    eventId: ev.eventId
  }
}];

const ev = $json;
return [{
  json: {
    status: 'RECORDED',
    eventType: 'ticket.checked_in',
    eventId: ev.eventId,
    ticketId: ev.checkIn?.ticketId,
    checkedInAt: ev.checkIn?.checkedInAt,
    message: 'Check-in recorded in audit trail successfully; no customer email dispatched.'
  }
}];

parameters.responseBody:
{
  "success": true,
  "eventId": "={{ $json.eventId }}",
  "status": "DELIVERED",
  "message": "Event processed and notification delivered successfully."
}
